import{_ as d,C as i,o as s,c as u,j as e,a as n,E as l,a3 as o}from"./chunks/framework.D4-ViStF.js";const y=JSON.parse('{"title":"序卦传","description":"讲六十四卦次序之理的传——从天地万物、夫妇人伦到既济未济，读懂卦与卦之间为什么这样相承。","frontmatter":{"title":"序卦传","description":"讲六十四卦次序之理的传——从天地万物、夫妇人伦到既济未济，读懂卦与卦之间为什么这样相承。","category":"guide","aliases":["序卦传","序卦","xu gua zhuan"],"source":["《周易·序卦传》"]},"headers":[],"relativePath":"yijing/shi-yi/xu-gua-zhuan.md","filePath":"yijing/shi-yi/xu-gua-zhuan.md","lastUpdated":1788516578000}'),c={name:"yijing/shi-yi/xu-gua-zhuan.md"};function p(m,a,g,b,x,q){const r=i("DaoReadingPrelude"),t=i("DaoTextReading"),h=i("DaoKeywordCards");return s(),u("div",null,[a[0]||(a[0]=e("h1",{id:"序卦传",tabindex:"-1"},[n("序卦传 "),e("a",{class:"header-anchor",href:"#序卦传","aria-label":'Permalink to "序卦传"'},"​")],-1)),l(r,{title:"顺着卦与卦之间的理由读",summary:"《序卦传》篇幅不长，却回答了一个重要问题：六十四卦为什么要这样排列？它用「故受之以」把相邻卦连接起来，从天地、万物、资源、冲突与秩序，写到家庭、进退、聚散、动止、诚信，最后落在既济而未济。读它，不是背一串编号，而是看见局面如何生出下一局面。",points:[{label:"先看连接",text:"留意每个「故受之以」：它说明上一种状态为什么会引出下一种状态。"},{label:"再看转折",text:"通会转否，盛会转剥，困会求解；没有一种局面可以永远停留。"},{label:"最后回到人",text:"上经从天地万物展开，下经转入夫妇、家庭、社会与人的进退。"}],hint:"《序卦》提供的是一幅变化地图，不是要求现实必须按六十四步机械运行的剧本。先读它的因果意识，再回到具体卦义。"}),a[1]||(a[1]=o('<h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>《序卦传》是《易传》中专门解释六十四卦次序的一篇。它不逐卦详细解释卦辞、爻辞，而是用极简的因果句式，说明一个卦为什么承接前一个卦。</p><p>「受之以」可以理解为「接下来由某卦承接」。这种承接不是简单的时间先后，而是从一类处境转向另一类处境的结构理由：物生而蒙，蒙而需，需而讼；通而否，否而同人；有大而谦，谦而豫，豫而随，随而蛊。</p><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><ul><li>六十四卦不再是彼此孤立的六十四张图，而成为一部有起承转合的变化之书。</li><li>它让读者看到「状态会转化」：生之后有养，养之后有争，通之后有塞，成之后仍有未成。</li><li>它把宏观宇宙和具体人事连接起来：天地生万物，万物进入夫妇、父子、君臣、上下与礼义。</li><li>它提供了一种阅读和思考方法：不只问「这是什么卦」，还问「它由什么而来，又会把什么带出来」。</li></ul><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>先顺读全文，圈出反复出现的连接词：「必」「然后」「不可以终」「穷」「反」「故」。</li><li>再按上经、下经分组：上经从乾坤到坎离，重在天地万物与通塞；下经从咸恒到既济未济，重在人伦人事与行动。</li><li>不急着把次序读成现实的唯一流程。它更像常见发展逻辑的地图，帮助我们观察局势中的趋势和转折。</li><li>选一组相邻卦回到卦页，例如「泰—否」「剥—复」「困—井—革—鼎」，对照卦辞、彖辞与象辞，看看序卦的连接是否打开了新的角度。</li></ol><h2 id="核心内容要点" tabindex="-1">核心内容要点 <a class="header-anchor" href="#核心内容要点" aria-label="Permalink to &quot;核心内容要点&quot;">​</a></h2><ul><li><strong>天地生万物</strong>：乾坤之后先有屯、蒙，说明万物初生必然带着艰难与蒙昧。</li><li><strong>生存进入关系</strong>：需关乎饮食与供养，饮食涉及分配，分配容易引起讼，讼扩大而成师，众聚而需比。</li><li><strong>积蓄与礼</strong>：比之后有小畜，物畜然后有履；资源和力量必须通过礼与分寸，才能走向安定。</li><li><strong>通塞循环</strong>：泰之后有否，否之后有同人；通不会永远通，闭塞也不会永远闭塞。</li><li><strong>盛大须谦</strong>：同人而大有，有大不可盈，所以受之以谦；谦能承载豫悦，过度随喜又可能积成蛊弊。</li><li><strong>剥极必复</strong>：剥落不可能终尽，穷上反下而复；复而不妄，才能重新积蓄、养成与行动。</li><li><strong>人伦展开</strong>：天地、万物、男女、夫妇、父子、君臣、上下，逐层形成礼义可以安置的关系空间。</li><li><strong>进退与聚散</strong>：恒、遁、大壮、晋、明夷、家人、睽、蹇、解，写出行动、受伤、归家、乖离和解难的反复。</li><li><strong>终而未终</strong>：既济代表事情已成，未济提醒万物不可穷，完成不是变化的终点。</li></ul><h2 id="与六十四卦的联动" tabindex="-1">与六十四卦的联动 <a class="header-anchor" href="#与六十四卦的联动" aria-label="Permalink to &quot;与六十四卦的联动&quot;">​</a></h2><ul><li>逐卦阅读入口：<a href="/Dao/yijing/hexagrams/"><code>六十四卦目录</code></a>。每一卦都可以先查它在序卦中的来处与去向。</li><li>上经首尾：从乾坤的天地定位，走到坎离的陷与丽；下经则从咸恒的感与久，走到既济未济。</li><li>可重点对照 <code>hexagram-11</code>（泰）与 <code>hexagram-12</code>（否）、<code>hexagram-23</code>（剥）与 <code>hexagram-24</code>（复）、<code>hexagram-63</code>（既济）与 <code>hexagram-64</code>（未济）。</li><li>与 <a href="/Dao/yijing/shi-yi/za-gua-zhuan"><code>杂卦传</code></a> 对读：序卦讲「为什么这样排列」，杂卦讲「每个卦以什么卦德相对」。</li></ul><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2>',12)),l(t,{colophon:"天地生物 · 通塞相因 · 人伦展开 · 既济未济",tone:"ink",sections:[{id:"duan-01",sentences:[["有天地，然后万物生焉。盈天地之间者唯万物，故受之以《屯》。"],["屯者，盈也。屯者，物之始生也。物生必蒙，故受之以《蒙》。"],["蒙者，蒙也，物之稚也。物稚不可不养也，故受之以《需》。"],["需者，饮食之道也。饮食必有讼，故受之以《讼》。讼必有众起，故受之以《师》。"],["师者，众也。众必有所比，故受之以《比》。比者，比也。比必有所畜，故受之以《小畜》。"],["物畜然后有礼，故受之以《履》。履而泰，然后安，故受之以《泰》。泰者，通也。"],["物不可以终通，故受之以《否》。物不可以终否，故受之以《同人》。与人同者，物必归焉，故受之以《大有》。"],["有大者，不可以盈，故受之以《谦》。有大而能谦必豫，故受之以《豫》。豫必有随，故受之以《随》。以喜随人者必有事，故受之以《蛊》。"]]},{id:"duan-02",sentences:[["蛊者，事也。有事而后可大，故受之以《临》。临者，大也。物大然后可观，故受之以《观》。"],["可观而后有所合，故受之以《噬嗑》。嗑者，合也。物不可以苟合而已，故受之以《贲》。"],["贲者，饰也。致饰然后亨则尽矣，故受之以《剥》。剥者，剥也。"],["物不可以终尽剥，穷上反下，故受之以《复》。复则不妄矣，故受之以《无妄》。"],["有无妄，物然后可畜，故受之以《大畜》。物畜然后可养，故受之以《颐》。颐者，养也。"],["不养则不可动，故受之以《大过》。物不可以终过，故受之以《坎》。坎者，陷也。陷必有所丽，故受之以《离》。离者，丽也。"]]},{id:"duan-03",sentences:[["有天地然后有万物，有万物然后有男女，有男女然后有夫妇，有夫妇然后有父子，有父子然后有君臣，有君臣然后有上下，有上下然后礼义有所错。"],["夫妇之道不可以不久也，故受之以《恒》。恒者，久也。物不可以久居其所，故受之以《遁》。遁者，退也。"],["物不可以终遁，故受之以《大壮》。物不可以终壮，故受之以《晋》。晋者，进也。进必有所伤，故受之以《明夷》。"],["夷者，伤也。伤于外者必反于家，故受之以《家人》。家道穷必乖，故受之以《睽》。睽者，乖也。"]]},{id:"duan-04",sentences:[["乖必有难，故受之以《蹇》。蹇者，难也。物不可以终难，故受之以《解》。解者，缓也。"],["缓必有所失，故受之以《损》。损而不已必益，故受之以《益》。益而不已必决，故受之以《夬》。夬者，决也。"],["决必有遇，故受之以《姤》。姤者，遇也。物相遇而后聚，故受之以《萃》。萃者，聚也。"],["聚而上者谓之升，故受之以《升》。升而不已必困，故受之以《困》。困乎上者必反下，故受之以《井》。"],["井道不可不革，故受之以《革》。革物者莫若鼎，故受之以《鼎》。主器者莫若长子，故受之以《震》。震者，动也。"],["物不可以终动，止之，故受之以《艮》。艮者，止也。物不可以终止，故受之以《渐》。渐者，进也。"]]},{id:"duan-05",sentences:[["进必有所归，故受之以《归妹》。得其所归者必大，故受之以《丰》。丰者，大也。穷大者必失其居，故受之以《旅》。"],["旅而无所容，故受之以《巽》。巽者，入也。入而后说之，故受之以《兑》。兑者，说也。"],["说而后散之，故受之以《涣》。涣者，离也。物不可以终离，故受之以《节》。"],["节而信之，故受之以《中孚》。有其信者必行之，故受之以《小过》。有过物者必济，故受之以《既济》。"],["物不可穷也，故受之以《未济》，终焉。"]]}],"aria-label":"序卦传原文"}),a[2]||(a[2]=e("blockquote",null,[e("p",null,"注：本页按你提供的通行本文字整理。不同底本在「遁／遁」「无／無」「错／措」「说／悦」等字形、用字和句读上可能有差异，阅读时请以所据版本为准。")],-1)),a[3]||(a[3]=e("h2",{id:"【原典层】字词释义",tabindex:"-1"},[n("【原典层】字词释义 "),e("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),l(h,{items:[{term:"序卦",pinyin:["xù","guà"],meaning:"说明六十四卦次序与相承理由的《易传》篇名。它关注卦与卦之间的关系，不是逐卦详解。"},{term:"受之以",pinyin:["shòu","zhī","yǐ"],meaning:"承接、接续于某卦。每一个「故受之以」都在回答：前一状态为什么会带出后一状态。"},{term:"屯",pinyin:["zhūn"],meaning:"聚集、艰难，也指万物初生而未舒展的状态。新生之物有生机，也有条件未备的纠结。"},{term:"蒙",pinyin:["méng"],meaning:"蒙昧、幼稚。物初生而未明，需要养育、学习与引导；蒙不是终点，而是进入学习的起点。"},{term:"履",pinyin:["lǚ"],meaning:"践履、行走，也含有依礼而行、守分知止的意味。物畜之后不能只凭力量，还需要分寸。"},{term:"泰",pinyin:["tài"],meaning:"通达、通泰。序卦强调「物不可以终通」，提醒顺境不能被当成永恒状态。"},{term:"否",pinyin:["pǐ"],meaning:"闭塞、不通。否并非终局，序卦接着以同人说明闭塞中仍会重新产生共同与连接。"},{term:"蛊",pinyin:["gǔ"],meaning:"积弊、败坏之事，也包含整治积弊的任务。随喜而失察，久而久之便可能生蛊。"},{term:"剥复",pinyin:["bō","fù"],meaning:"剥是剥落，复是返回、复生。剥极不能终尽，穷上反下而复，构成《易》重要的转化节律。"},{term:"咸恒",pinyin:["xián","héng"],meaning:"咸为感应，恒为长久。下经由夫妇之道开端，写人与人如何感通并在关系中求久。"},{term:"既济",pinyin:["jì","jì"],meaning:"事情已经渡过、已经完成的状态。它虽成而未必永固，因此下一卦仍是未济。"},{term:"未济",pinyin:["wèi","jì"],meaning:"尚未渡过、尚未完成。它不是单纯失败，而是保留变化和继续行动的开放结尾。"}]}),a[4]||(a[4]=o('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><blockquote><p>以下内容根据本次整理稿归纳，先帮助读者进入《序卦》的阅读方法，不把它当成六十四卦唯一、固定的解释系统。</p></blockquote><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>《序卦》把六十四卦串成一条变化之路：天地开辟，万物初生；初生必蒙，需要养育；有了饮食与资源，就进入争讼、群体与合作；积蓄之后要有礼，通泰之后会遇闭塞；人与人重新同道，又会得到资源和成就，但成就不能盈满，仍要回到谦。</p><p>下经把视线从万物推进到人伦：有男女而有夫妇，有夫妇而有父子、君臣、上下，礼义才有安置的空间。此后又有久、退、壮、进、伤、归家、乖离、困难、解脱，直到聚散、升降、革鼎、动止、渐进、归属、丰旅、入说、离散、节制、诚信、行动与完成。</p><h3 id="理-为什么次序本身值得读" tabindex="-1">理：为什么次序本身值得读 <a class="header-anchor" href="#理-为什么次序本身值得读" aria-label="Permalink to &quot;理：为什么次序本身值得读&quot;">​</a></h3><ul><li>每个「然后」都在表达一种发生学：状态不是凭空出现，而有前一阶段的条件。</li><li>每个「不可以终」都在表达变化观：通、否、剥、遁、壮、止、离都不能永久固定。</li><li>上经偏向天地万物的展开，下经偏向人伦关系的展开，但两者并非割裂，都是在讲阴阳、刚柔、聚散与进退。</li><li>「既济」之后仍是「未济」，说明完成只能是阶段性完成；事情越接近结束，越要保留对新变化的觉察。</li></ul><h3 id="用-今天怎么读一局变化" tabindex="-1">用：今天怎么读一局变化 <a class="header-anchor" href="#用-今天怎么读一局变化" aria-label="Permalink to &quot;用：今天怎么读一局变化&quot;">​</a></h3><p>遇到一个处境时，可以沿着《序卦》的方法问：</p><ul><li>我现在处在「屯、蒙、需、讼、泰、否」中的哪一类状态？是在生长、等待、争执，还是暂时不通？</li><li>当前局面由什么积累而来，又在孕育什么下一步？我是在小畜之后建立履，还是在豫随之后忽略了蛊？</li><li>事情看似已经既济时，有没有仍未完成的部分？事情陷入剥、困或未济时，是否仍能找到复、解、井或新的连接？</li></ul><h2 id="【解读层】分段解读" tabindex="-1">【解读层】分段解读 <a class="header-anchor" href="#【解读层】分段解读" aria-label="Permalink to &quot;【解读层】分段解读&quot;">​</a></h2><h3 id="一、从天地万物到秩序-上经前半" tabindex="-1">一、从天地万物到秩序：上经前半 <a class="header-anchor" href="#一、从天地万物到秩序-上经前半" aria-label="Permalink to &quot;一、从天地万物到秩序：上经前半&quot;">​</a></h3><p>《乾》《坤》之后是《屯》《蒙》，先说明新生必有艰难和蒙昧；《需》写供养与等待，《讼》写资源分配后的争执，《师》《比》写冲突扩大后形成组织、群体与亲比。</p><p>接着是《小畜》《履》《泰》《否》：积蓄不能只用于扩张，还需要礼与分寸；有礼而能履，才可能通泰与安定，但通泰不可能无尽，闭塞因此成为下一种需要面对的状态。</p><p>《同人》《大有》《谦》《豫》《随》《蛊》则写成就之后的风险。与人同道，资源归聚而大有；有大却不能盈满，必须以谦承载；谦而豫，豫而随，但一味随喜、只享受顺境而不处理积弊，便会进入蛊。</p><h3 id="二、从整治积弊到剥复-上经后半" tabindex="-1">二、从整治积弊到剥复：上经后半 <a class="header-anchor" href="#二、从整治积弊到剥复-上经后半" aria-label="Permalink to &quot;二、从整治积弊到剥复：上经后半&quot;">​</a></h3><p>《蛊》不是只能停留在败坏里，有事而后可大，所以进入《临》《观》《噬嗑》。先临事、扩大视野，再观其情势；看见阻隔之后，必须噬嗑，使事情真正相合，而不能苟合。</p><p>《贲》提醒文饰与秩序的价值，《剥》又提醒文饰过度会掏空根基。剥落不可能终尽，穷上反下而《复》；复而不妄，才能进入《大畜》《颐》的蓄养。养而不动又可能过度，于是有《大过》《坎》《离》：过盛进入险陷，险陷中仍要有所附丽、有所照明。</p><h3 id="三、从夫妇人伦到进退-下经前半" tabindex="-1">三、从夫妇人伦到进退：下经前半 <a class="header-anchor" href="#三、从夫妇人伦到进退-下经前半" aria-label="Permalink to &quot;三、从夫妇人伦到进退：下经前半&quot;">​</a></h3><p>下经以天地、万物、男女、夫妇、父子、君臣、上下的展开说明礼义如何落地。夫妇之道不能不久，所以有《恒》；但任何事也不能久居其所，所以有《遁》。退不是永远逃避，退到一定阶段还要重新振作，于是有《大壮》《晋》。</p><p>进必有所伤，受伤于外又反于家；家道穷则乖离，亲近处也不是自动和谐的避风港。《明夷》《家人》《睽》连在一起，写的是人在现实受伤后如何回到关系，而关系内部又如何需要持续修补。</p><h3 id="四、由难而解-由损益而决-下经后半" tabindex="-1">四、由难而解，由损益而决：下经后半 <a class="header-anchor" href="#四、由难而解-由损益而决-下经后半" aria-label="Permalink to &quot;四、由难而解，由损益而决：下经后半&quot;">​</a></h3><p>《蹇》说明乖离之后会有困难，《解》说明困难不能永远持续，必须缓解和解除；但解之后也会有所失，于是进入《损》。损不是纯粹的减少，减去过度之后才可能真正受益，所以有《益》；益而不已又必须决断，故有《夬》《姤》《萃》《升》。</p><p>聚而上升，升而不已又会困；困乎上而反下，回到可以持续供养的《井》；井道不能永远不变，所以需要《革》，革物最适合借《鼎》来完成，而主器又要有能够承担的人，于是由鼎到震、艮，形成动止相济的次序。</p><h3 id="五、由渐进到未济-最后一段的开放结尾" tabindex="-1">五、由渐进到未济：最后一段的开放结尾 <a class="header-anchor" href="#五、由渐进到未济-最后一段的开放结尾" aria-label="Permalink to &quot;五、由渐进到未济：最后一段的开放结尾&quot;">​</a></h3><p>《渐》不是突然飞跃，而是有次序地进；进必有所归，归而能得其所则大，丰大到极处又可能失去居所，成为《旅》。旅无所容，才需要巽入；进入之后有兑悦，悦之后还会涣散。</p><p>散不能无尽，于是有《节》；节而能信，才有《中孚》；有信还要能够实践，所以有《小过》。过而能济，事情暂时抵达《既济》，但万物不可穷，最终仍以《未济》收束。</p><h3 id="六、与《四象论》的互文" tabindex="-1">六、与《四象论》的互文 <a class="header-anchor" href="#六、与《四象论》的互文" aria-label="Permalink to &quot;六、与《四象论》的互文&quot;">​</a></h3><p>《序卦》适合与站内的<a href="/Dao/topics/traditional-wisdom/01-philosophy/03-four-symbols"><code>四象论</code></a>交叉阅读：四象论辨析阴阳分化的变化状态与四方天文的空间结构，序卦则展示六十四卦如何把变化组织成前后相承的路径。二者都提醒我们，传统概念之间可以后世会通，但阅读时仍要分清各自文本的层次和功能。</p><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>万事不是突然变成现在的样子。一个新事物先要经历初生的混乱，接着需要学习、资源和养护；资源一多，就会产生分配与争执；争执扩大，需要组织和合作；合作稳定后，要建立边界与礼；顺利之后仍会遇到闭塞，成就之后也必须保持谦逊。</p><p>当问题积久成弊，就要面对它、看清它、处理它；表面的修饰不能代替根基，剥落之后仍可能重新开始。人与人建立关系、共同生活，也会经历长久、退守、进取、受伤、归家、乖离、困难和化解。</p><p>因此，《序卦》不是说人生只能依次走完六十四步，而是训练一种看局势的能力：看到前因，预见后果；知道通会转塞，盛会转衰，成事之后仍有未成；在变化中不把任何阶段误认为永恒。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><p>《序卦》最值得留下的不是一套方便背诵的卦序口诀，而是「每一局都会带出下一局」的意识。它让人不把困难看成凭空降临，也不把顺利看成理所当然。</p><p>对我来说，读《序卦》可以暂时只保留三件事：</p><ul><li>看见事情从哪里来，不把结果和前因切开；</li><li>看见当前状态的边界，不把通泰、困厄、完成或停滞当成永久；</li><li>在「既济」处仍保留对「未济」的清醒，在「未济」处也不放弃下一次通达的可能。</li></ul><h2 id="延伸阅读-参考来源" tabindex="-1">延伸阅读 / 参考来源 <a class="header-anchor" href="#延伸阅读-参考来源" aria-label="Permalink to &quot;延伸阅读 / 参考来源&quot;">​</a></h2><ul><li>上一篇：<a href="/Dao/yijing/shi-yi/xi-ci-zhuan-xia"><code>系辞下传</code></a></li><li>下一篇：<a href="/Dao/yijing/shi-yi/za-gua-zhuan"><code>杂卦传</code></a></li><li>十翼总览：<a href="/Dao/yijing/shi-yi/"><code>孔子十翼</code></a></li><li>六十四卦目录：<a href="/Dao/yijing/hexagrams/"><code>文王六十四卦</code></a></li><li>相关专题：<a href="/Dao/topics/traditional-wisdom/01-philosophy/03-four-symbols"><code>四象论</code></a></li><li>通行本《周易·序卦传》（王弼注、孔颖达疏系统）</li></ul>',39))])}const _=d(c,[["render",p]]);export{y as __pageData,_ as default};
